'use strict';
const validRate=d=>d.target!==null&&d.target!==0&&d.actual!==null&&d.rate!==null;
const pct=v=>v===null?'—':v.toFixed(2)+'%';
function taskScores(rows,limit=150){const groups=new Map();for(const d of rows){if(!groups.has(d.code))groups.set(d.code,[]);groups.get(d.code).push(d);}return [...groups].map(([code,items])=>{const v=items.filter(d=>validRate(d)&&d.weight!==null&&d.weight>=0),sum=v.reduce((a,d)=>a+d.weight,0);return{code,area:code[0],title:items[0].task,raw:sum?v.reduce((a,d)=>a+d.rate*d.weight,0)/sum:null,cap:sum?v.reduce((a,d)=>a+Math.min(d.rate,limit)*d.weight,0)/sum:null,weight:sum,items};});}
const mean=(rows,key)=>{const v=rows.map(d=>d[key]).filter(v=>v!==null);return v.length?v.reduce((a,b)=>a+b,0)/v.length:null;};
function renderAnalysis(rows,all){
 $('comparison-area-heading').textContent='영역별 '+groupName()+' 평균';
 $('comparison-method').textContent=isStrategyView()?'전략과제는 소속 실행과제 점수의 단순평균입니다. 상한은 세부지표에 적용한 뒤 실행과제, 전략과제 순으로 계산합니다.':'세부지표 달성률을 먼저 제한한 뒤 실행과제별 가중평균을 계산합니다.';
 const limit=Number($('cap-limit').value),tasks=viewScores(rows,limit),valid=tasks.filter(d=>d.raw!==null),raw=mean(tasks,'raw'),cap=mean(tasks,'cap'),changes=tasks.filter(d=>d.raw!==null&&d.raw>=100&&d.cap<100),low=rows.filter(d=>validRate(d)&&d.rate<80).sort((a,b)=>a.rate-b.rate),high=rows.filter(d=>validRate(d)&&d.rate>=130).sort((a,b)=>b.rate-a.rate),unknown=rows.filter(d=>!validRate(d));
 $('cap-summary').innerHTML=[[groupName()+' 평균 · 원값',pct(raw)],[limit+'% 상한 적용 평균',pct(cap)],['평균 변화',raw===null||cap===null?'—':(cap-raw).toFixed(2)+'%p'],['달성 '+groupName(),valid.filter(d=>d.raw>=100).length+' → '+valid.filter(d=>d.cap>=100).length+'개']].map(([l,v])=>'<div class="cap-stat"><span>'+l+'</span><strong>'+v+'</strong></div>').join('');
 $('cap-heading').textContent=limit+'% 상한 적용 전후 비교'; $('cap-basis').textContent=limit===150?'보고서 기준 · 보조 지표':'130% 상한 시나리오 · 보조 지표';
 const partial=isStrategyView()?0:tasks.filter(t=>t.items.length!==all.filter(d=>d.code===t.code).length).length;
 $('cap-context').textContent='현재 필터: '+rows.length+'개 세부지표 / '+valid.length+'개 산출 가능한 '+groupName()+'. '+(partial?'필터로 '+partial+'개 과제의 일부 지표만 포함되어 가중치를 재정규화한 부분 계산입니다. 전체 과제 판정과 다를 수 있습니다.':isStrategyView()?'산출 가능한 소속 실행과제 점수의 단순평균입니다.':'실행과제에 속한 산출 가능한 지표의 가중치 합으로 나누어 계산합니다.')+' 산출불가 '+unknown.length+'개는 평균 및 구간 목록에서 제외합니다.';
 $('cap-areas').innerHTML='<thead><tr><th>영역</th><th>'+groupName()+' 수</th><th>평균 원값</th><th>상한 적용</th><th>변화(%p)</th></tr></thead><tbody>'+Object.entries(areas).map(([a,label])=>{const arr=tasks.filter(d=>d.area===a),x=mean(arr,'raw'),y=mean(arr,'cap');return'<tr><td>'+a+' · '+label+'</td><td>'+arr.filter(d=>d.raw!==null).length+'</td><td>'+pct(x)+'</td><td>'+pct(y)+'</td><td>'+(x===null?'—':(y-x).toFixed(2))+'</td></tr>';}).join('')+'</tbody>';
 $('cap-changes').innerHTML=changes.length?'<table><thead><tr><th>'+groupName()+'</th><th>원값</th><th>상한 적용</th><th>판정 변화</th></tr></thead><tbody>'+changes.map(t=>'<tr><td><b>'+esc(t.code)+'</b><small>'+esc(t.title)+'</small></td><td>'+pct(t.raw)+'</td><td>'+pct(t.cap)+'</td><td><span class="tag bad">달성 → 미달성</span></td></tr>').join('')+'</tbody></table>':'<p>현재 필터에서 달성 → 미달성으로 전환되는 실행과제가 없습니다.</p>';
 renderReview(rows,taskScores(rows,limit),limit);
 $('excluded-list').innerHTML=unknown.length?'<summary>산출불가 지표 '+unknown.length+'개 보기</summary><ul>'+unknown.map(d=>'<li>'+esc(d.code)+' · '+esc(d.title)+' · '+esc(d.dept)+' · '+(d.target===0?'목표값 0':'목표·실적·달성률 결측')+'</li>').join('')+'</ul>':'<summary>산출불가 지표 없음</summary>';
 $('report-check').textContent='보고서 기준: 150% 상한, 실행과제 평균 139.71% → 106.55%, 달성 실행과제 44 → 41개. 현재 업로드 전체 자료('+limit+'% 상한): '+pct(mean(taskScores(all),'raw'))+' → '+pct(mean(taskScores(all,limit),'cap'))+'. 원본 엑셀의 달성 166개 중 목표값 0인 3개를 보고서는 산출불가로 분리하여 달성 163개로 집계합니다. 상단 카드는 원본 판정을 유지합니다.';
}
